interfaces:
class ShortenerProtocol(Protocol):
    def shorten(self, long_url: str, *, custom_alias: str | None = None) -> ShortLink: ...
    def resolve(self, code: str) -> str | None: ...

class CodeGeneratorProtocol(Protocol):
    def next_code(self) -> str: ...
    def is_valid(self, code: str) -> bool: ...

class StatsCollectorProtocol(Protocol):
    def record_click(self, event: ClickEvent) -> None: ...
    def stats_for(self, code: str) -> ClickStats: ...
